use async_trait::async_trait;
use fastembed::{EmbeddingModel, InitOptions, TextEmbedding};
use mem7_error::{Mem7Error, Result};
use std::sync::{Arc, Mutex};
use tracing::debug;

use crate::EmbeddingClient;

pub struct FastEmbedClient {
    model: Arc<Mutex<TextEmbedding>>,
}

impl FastEmbedClient {
    pub fn new(model_name: &str, cache_dir: Option<&str>) -> Result<Self> {
        let embedding_model = parse_model(model_name)?;

        let mut opts = InitOptions::new(embedding_model).with_show_download_progress(true);
        if let Some(dir) = cache_dir {
            opts = opts.with_cache_dir(dir.into());
        }

        let model = TextEmbedding::try_new(opts)
            .map_err(|e| Mem7Error::Embedding(format!("fastembed init: {e}")))?;

        debug!(model = model_name, "FastEmbed model loaded");

        Ok(Self {
            model: Arc::new(Mutex::new(model)),
        })
    }
}

#[async_trait]
impl EmbeddingClient for FastEmbedClient {
    async fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        let model = self.model.clone();
        let docs: Vec<String> = texts.to_vec();

        tokio::task::spawn_blocking(move || {
            let refs: Vec<&str> = docs.iter().map(|s| s.as_str()).collect();
            let mut guard = model
                .lock()
                .map_err(|e| Mem7Error::Embedding(format!("fastembed lock: {e}")))?;
            guard
                .embed(refs, None)
                .map_err(|e| Mem7Error::Embedding(format!("fastembed embed: {e}")))
        })
        .await
        .map_err(|e| Mem7Error::Embedding(format!("fastembed task join: {e}")))?
    }
}

fn parse_model(name: &str) -> Result<EmbeddingModel> {
    let model = match name {
        "AllMiniLML6V2" | "all-MiniLM-L6-v2" => EmbeddingModel::AllMiniLML6V2,
        "AllMiniLML6V2Q" | "all-MiniLM-L6-v2-q" => EmbeddingModel::AllMiniLML6V2Q,
        "AllMiniLML12V2" | "all-MiniLM-L12-v2" => EmbeddingModel::AllMiniLML12V2,
        "AllMiniLML12V2Q" | "all-MiniLM-L12-v2-q" => EmbeddingModel::AllMiniLML12V2Q,
        "BGEBaseENV15" | "BAAI/bge-base-en-v1.5" => EmbeddingModel::BGEBaseENV15,
        "BGEBaseENV15Q" | "BAAI/bge-base-en-v1.5-q" => EmbeddingModel::BGEBaseENV15Q,
        "BGESmallENV15" | "BAAI/bge-small-en-v1.5" => EmbeddingModel::BGESmallENV15,
        "BGESmallENV15Q" | "BAAI/bge-small-en-v1.5-q" => EmbeddingModel::BGESmallENV15Q,
        "BGELargeENV15" | "BAAI/bge-large-en-v1.5" => EmbeddingModel::BGELargeENV15,
        "BGELargeENV15Q" | "BAAI/bge-large-en-v1.5-q" => EmbeddingModel::BGELargeENV15Q,
        "NomicEmbedTextV1" | "nomic-embed-text-v1" => EmbeddingModel::NomicEmbedTextV1,
        "NomicEmbedTextV15" | "nomic-embed-text-v1.5" => EmbeddingModel::NomicEmbedTextV15,
        "NomicEmbedTextV15Q" | "nomic-embed-text-v1.5-q" => EmbeddingModel::NomicEmbedTextV15Q,
        "MultilingualE5Small" | "multilingual-e5-small" => EmbeddingModel::MultilingualE5Small,
        "MultilingualE5Base" | "multilingual-e5-base" => EmbeddingModel::MultilingualE5Base,
        "MultilingualE5Large" | "multilingual-e5-large" => EmbeddingModel::MultilingualE5Large,
        "MxbaiEmbedLargeV1" | "mxbai-embed-large-v1" => EmbeddingModel::MxbaiEmbedLargeV1,
        "MxbaiEmbedLargeV1Q" | "mxbai-embed-large-v1-q" => EmbeddingModel::MxbaiEmbedLargeV1Q,
        "GTEBaseENV15" | "gte-base-en-v1.5" => EmbeddingModel::GTEBaseENV15,
        "GTEBaseENV15Q" | "gte-base-en-v1.5-q" => EmbeddingModel::GTEBaseENV15Q,
        "GTELargeENV15" | "gte-large-en-v1.5" => EmbeddingModel::GTELargeENV15,
        "GTELargeENV15Q" | "gte-large-en-v1.5-q" => EmbeddingModel::GTELargeENV15Q,
        _ => {
            return Err(Mem7Error::Config(format!(
                "unknown fastembed model: {name}. Use TextEmbedding::list_supported_models() for available models."
            )));
        }
    };
    Ok(model)
}

document.addEventListener("DOMContentLoaded", () => {
  setupTabs(".install-tab", "data-install", ".install-panel", "data-install-panel");
  setupTabs(".code-tab", "data-lang", ".code-panel", "data-lang-panel");
  setupTabs("[data-decay]", "data-decay", "[data-decay-panel]", "data-decay-panel");
  setupTabs("[data-context]", "data-context", "[data-context-panel]", "data-context-panel");
  setupCopyButtons();
  setupThemeToggle();
  renderKatex();
});

function renderKatex() {
  if (typeof katex === "undefined") {
    setTimeout(renderKatex, 100);
    return;
  }
  document.querySelectorAll("[data-katex]").forEach((el) => {
    katex.render(el.getAttribute("data-katex"), el, {
      displayMode: true,
      throwOnError: false,
    });
  });
}

function setupTabs(tabSelector, tabAttr, panelSelector, panelAttr) {
  const tabs = document.querySelectorAll(tabSelector);
  const panels = document.querySelectorAll(panelSelector);

  tabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      const value = tab.getAttribute(tabAttr);

      tabs.forEach((t) => t.classList.remove("active"));
      panels.forEach((p) => p.classList.remove("active"));

      tab.classList.add("active");
      const target = document.querySelector(`[${panelAttr}="${value}"]`);
      if (target) target.classList.add("active");
    });
  });
}

function setupThemeToggle() {
  const btn = document.querySelector(".theme-toggle");
  if (!btn) return;

  const saved = localStorage.getItem("mem7-theme");
  if (saved) {
    document.documentElement.setAttribute("data-theme", saved);
  } else if (window.matchMedia("(prefers-color-scheme: light)").matches) {
    document.documentElement.setAttribute("data-theme", "light");
  }

  btn.addEventListener("click", () => {
    const current = document.documentElement.getAttribute("data-theme");
    const next = current === "light" ? "dark" : "light";
    document.documentElement.setAttribute("data-theme", next);
    localStorage.setItem("mem7-theme", next);
  });

  window.matchMedia("(prefers-color-scheme: light)").addEventListener("change", (e) => {
    if (!localStorage.getItem("mem7-theme")) {
      document.documentElement.setAttribute("data-theme", e.matches ? "light" : "dark");
    }
  });
}

function setupCopyButtons() {
  document.querySelectorAll(".copy-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      let text = btn.getAttribute("data-copy");

      if (!text) {
        const codeId = btn.getAttribute("data-copy-code");
        if (codeId) {
          const codeEl = document.getElementById(`code-${codeId}`);
          if (codeEl) text = codeEl.textContent;
        }
      }

      if (!text) return;

      navigator.clipboard.writeText(text).then(() => {
        btn.classList.add("copied");
        const svg = btn.querySelector("svg");
        const original = svg.innerHTML;
        svg.innerHTML =
          '<polyline points="20 6 9 17 4 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>';
        setTimeout(() => {
          btn.classList.remove("copied");
          svg.innerHTML = original;
        }, 1500);
      });
    });
  });
}

/**
 * mem7 Demo — Ollama + Upstash Vector (TypeScript)
 *
 * Prerequisites:
 *   1. Ollama running with models pulled:
 *        ollama serve
 *        ollama pull qwen2.5:7b
 *        ollama pull mxbai-embed-large
 *   2. Environment variables set:
 *        UPSTASH_VECTOR_REST_URL=https://your-index.upstash.io
 *        UPSTASH_VECTOR_REST_TOKEN=<REDACTED>
 *   3. Install the package:
 *        npm install @mem7ai/mem7
 *
 * Run:
 *   npx tsx examples/mem7_demo.ts
 */

import { MemoryEngine } from "@mem7ai/mem7";

function pp(obj: unknown): void {
  console.log(JSON.stringify(obj, null, 2));
}

async function main() {
  // ── 1. Configure mem7 ────────────────────────────────────────────
  console.log("=== Initializing mem7 ===\n");

  const engine = await MemoryEngine.create(
    JSON.stringify({
      llm: {
        provider: "ollama",
        base_url: "http://localhost:11434/v1",
        api_key: "<REDACTED>",
        model: "qwen2.5:7b",
        temperature: 0.0,
        max_tokens: <REDACTED>
      },
      embedding: {
        provider: "ollama",
        base_url: "http://localhost:11434/v1",
        api_key: "<REDACTED>",
        model: "mxbai-embed-large",
        dims: 1024,
      },
      vector: {
        provider: "upstash",
        collection_name: "mem7-ts-test",
        dims: 1024,
        upstash_url: process.env.UPSTASH_VECTOR_REST_URL!,
        upstash_token: <REDACTED>
      },
      history: {
        db_path: ":memory:",
      },
      context: {
        enabled: true,
      },
    })
  );

  console.log("mem7 initialized\n");

  // ── 2. Reset (clean slate) ───────────────────────────────────────
  await engine.reset();
  console.log("reset done\n");

  // ── 3. Add memories from conversations ───────────────────────────
  console.log("=== Add memories ===\n");

  const result = await engine.add(
    [
      {
        role: "user",
        content:
          "I'm working on improving my tennis skills. I play twice a week.",
      },
      {
        role: "assistant",
        content:
          "That's great! Consistent practice is key. What areas are you focusing on?",
      },
      {
        role: "user",
        content:
          "I'm focusing on my backhand and serve. I also recently started taking lessons from a coach named Sarah.",
      },
    ],
    "alice"
  );
  console.log("Add result:");
  pp(result);
  console.log();

  const result2 = await engine.add(
    [
      {
        role: "user",
        content:
          "I recently moved to San Francisco and I love hiking in Marin.",
      },
    ],
    "alice"
  );
  console.log("Add result 2:");
  pp(result2);
  console.log();

  // ── 4. Search memories ───────────────────────────────────────────
  console.log("=== Search memories ===\n");

  const searchResults = await engine.search(
    "What sports does Alice play?",
    "alice",
    undefined,
    undefined,
    3
  );
  console.log("Search results:");
  pp(searchResults);
  console.log();

  // ── 5. Get all memories ──────────────────────────────────────────
  console.log("=== All memories ===\n");

  const allMemories = await engine.getAll("alice");
  console.log(`Total memories for alice: ${allMemories.length}`);
  pp(allMemories);
  console.log();

  // ── 6. Update with deduplication ─────────────────────────────────
  console.log("=== Add with deduplication ===\n");

  const result3 = await engine.add(
    [
      {
        role: "user",
        content:
          "I now play tennis three times a week and my coach Sarah says my backhand is improving a lot.",
      },
    ],
    "alice"
  );
  console.log("Add with dedup:");
  pp(result3);
  console.log();

  const allAfter = await engine.getAll("alice");
  console.log(`Total memories after dedup: ${allAfter.length}`);
  pp(allAfter);
  console.log();

  // ── 7. View history ──────────────────────────────────────────────
  console.log("=== History ===\n");

  if (allAfter.length > 0) {
    const firstId = allAfter[0].id;
    const history = await engine.history(firstId);
    console.log(`History for memory ${firstId}:`);
    pp(history);
    console.log();
  }

  // ── 8. Manual update & delete ────────────────────────────────────
  console.log("=== Manual update & delete ===\n");

  if (allAfter.length > 0) {
    const targetId = allAfter[0].id;

    console.log("Before update:");
    pp(await engine.get(targetId));

    await engine.update(
      targetId,
      "Alice is an advanced tennis player who trains daily."
    );
    console.log("\nAfter update:");
    pp(await engine.get(targetId));

    console.log("\nHistory after manual update:");
    pp(await engine.history(targetId));
    console.log();
  }

  if (allAfter.length > 1) {
    const delId = allAfter[allAfter.length - 1].id;
    console.log(`Deleting memory ${delId}`);
    await engine.delete(delId);
    const remaining = await engine.getAll("alice");
    console.log(`Remaining memories: ${remaining.length}\n`);
  }

  // ── 9. Multi-user isolation ──────────────────────────────────────
  console.log("=== Multi-user isolation ===\n");

  await engine.add(
    [
      {
        role: "user",
        content:
          "I'm a software engineer working on distributed systems in Rust.",
      },
    ],
    "bob"
  );

  console.log("Bob's memories:");
  pp(await engine.getAll("bob"));

  console.log("\nAlice's memories (unchanged):");
  pp(await engine.getAll("alice"));

  console.log('\nSearch "tennis" as Bob (expect nothing):');
  pp(await engine.search("tennis", "bob"));
  console.log();

  // ── 10. Context-aware search ─────────────────────────────────────
  console.log("=== Context-aware search ===\n");

  console.log("Auto-classified query:");
  pp(await engine.search("What sports does Alice play?", "alice", undefined, undefined, 3));

  console.log("\nOverride task_type = troubleshooting (preferences demoted):");
  pp(
    await engine.search(
      "What sports does Alice play?",
      "alice",
      undefined,
      undefined,
      3,
      undefined,
      undefined,
      undefined,
      "troubleshooting"
    )
  );

  console.log("\nMemory types in stored memories:");
  const mems = await engine.getAll("alice");
  for (const m of mems) {
    console.log(`  [${m.memoryType ?? "unknown"}] ${m.text}`);
  }
  console.log();

  // ── 11. Cleanup ──────────────────────────────────────────────────
  await engine.reset();
  console.log("All data cleared");
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});

import type { OpenClawPluginApi, PluginConfig } from "./config.js";
import { buildMem7Config } from "./config.js";
import { registerTools } from "./tools.js";
import { registerHooks } from "./hooks.js";
import type { Mem7Engine } from "./engine.js";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

export interface PluginEntry {
  id: string;
  name: string;
  description: string;
  kind: string;
  register(api: OpenClawPluginApi): void;
}

export default {
  id: "openclaw-mem7",
  name: "Memory (mem7)",
  description:
    "LLM-powered long-term memory with fact extraction, graph relations, dedup, and Ebbinghaus forgetting curve.",
  kind: "memory",

  register(api: OpenClawPluginApi): void {
    const pluginCfg = (api.pluginConfig ?? {}) as PluginConfig;
    const mem7ConfigJson = buildMem7Config(pluginCfg, api);

    let engine: Mem7Engine | null = null;

    const historyDb = (mem7ConfigJson.history as { db_path?: string })?.db_path;
    if (historyDb) {
      try {
        mkdirSync(dirname(historyDb), { recursive: true });
      } catch {
        // directory may already exist
      }
    }

    api.registerService({
      id: "openclaw-mem7",
      async start() {
        // Dynamic import -- types are provided by our local Mem7Engine interface,
        // not the npm package (which may lag behind the current Rust API).
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const mod: any = await import("@mem7ai/mem7");
        engine = await mod.MemoryEngine.create(JSON.stringify(mem7ConfigJson));
        api.logger.info("mem7 engine initialized");
      },
      async stop() {
        engine = null;
        api.logger.info("mem7 engine stopped");
      },
    });

    registerTools(api, () => engine, pluginCfg);
    registerHooks(api, () => engine, pluginCfg);
  },
} satisfies PluginEntry;

import { Type } from "@sinclair/typebox";
import type { OpenClawPluginApi, PluginConfig } from "./config.js";
import { resolveScopeIds, type MemoryScope } from "./config.js";
import {
  formatSearchResult,
  formatMemoryItem,
  formatMemoryList,
  formatAddResult,
  type MemoryItem,
  type SearchResult,
} from "./format.js";
import type { Mem7Engine, EngineGetter } from "./engine.js";

function requireEngine(getEngine: EngineGetter): Mem7Engine {
  const engine = getEngine();
  if (!engine) {
    throw new Error("mem7 engine is not initialized yet");
  }
  return engine;
}

const DEFAULT_SOURCE = "OPENCLAW";

const ScopeSchema = Type.Optional(
  Type.Union([Type.Literal("session"), Type.Literal("long-term"), Type.Literal("all")]),
);

type ToolScopeArgs = {
  userId?: string;
  agentId?: string;
  runId?: string;
  scope?: MemoryScope;
  longTerm?: boolean;
};

function normalizeScope(
  scope: MemoryScope | undefined,
  longTerm: boolean | undefined,
  defaultScope: MemoryScope,
): MemoryScope {
  if (scope) return scope;
  if (longTerm != null) return longTerm ? "long-term" : "session";
  return defaultScope;
}

function resolveToolScope(
  cfg: PluginConfig,
  api: OpenClawPluginApi,
  args: ToolScopeArgs,
  scope: Exclude<MemoryScope, "all">,
): { userId: string; agentId: string | null; runId: string | null } {
  return resolveScopeIds(cfg, api, {
    userId: args.userId,
    agentId: args.agentId,
    runId: args.runId,
    scope,
  });
}

function metadataJson(metadata?: Record<string, unknown>, agentId?: string | null): string {
  const payload: Record<string, unknown> = {
    source: DEFAULT_SOURCE,
    ...(metadata ?? {}),
  };
  if (agentId && payload.actor_id == null) {
    payload.actor_id = `agent:${agentId}`;
  }
  return JSON.stringify(payload);
}

function sourceFiltersJson(): string {
  return JSON.stringify({ source: DEFAULT_SOURCE });
}

function emptySearchResult(): SearchResult {
  return { memories: [], relations: [] };
}

function mergeSearchResults(results: SearchResult[], limit: number): SearchResult {
  const memoryMap = new Map<string, MemoryItem>();
  const relationKeys = new Set<string>();
  const relations: SearchResult["relations"] = [];

  for (const result of results) {
    for (const memory of result.memories) {
      if (!memoryMap.has(memory.id)) {
        memoryMap.set(memory.id, memory);
      }
    }
    for (const relation of result.relations) {
      const key = `${relation.source}|${relation.relationship}|${relation.destination}`;
      if (!relationKeys.has(key)) {
        relationKeys.add(key);
        relations.push(relation);
      }
    }
  }

  const memories = Array.from(memoryMap.values()).slice(0, limit);
  return {
    memories,
    relations,
  };
}

function mergeMemoryLists(lists: MemoryItem[][], limit: number): MemoryItem[] {
  const memoryMap = new Map<string, MemoryItem>();
  for (const list of lists) {
    for (const memory of list) {
      if (!memoryMap.has(memory.id)) {
        memoryMap.set(memory.id, memory);
      }
    }
  }
  return Array.from(memoryMap.values()).slice(0, limit);
}

async function searchMemories(
  engine: Mem7Engine,
  cfg: PluginConfig,
  api: OpenClawPluginApi,
  args: ToolScopeArgs & { query: string; limit?: number },
  defaultScope: MemoryScope = "all",
): Promise<SearchResult> {
  const scope = normalizeScope(args.scope, args.longTerm, defaultScope);
  const limit = args.limit ?? cfg.topK ?? 5;
  const filters = sourceFiltersJson();
  const threshold = cfg.searchThreshold ?? null;

  if (scope === "all") {
    const longTermScope = resolveToolScope(cfg, api, args, "long-term");
    const sessionScope = resolveToolScope(cfg, api, args, "session");

    const results: SearchResult[] = [
      await engine.search(
        args.query,
        longTermScope.userId,
        longTermScope.agentId,
        longTermScope.runId,
        limit,
        filters,
        true,
        threshold,
      ),
    ];

    if (sessionScope.runId) {
      results.push(
        await engine.search(
          args.query,
          sessionScope.userId,
          sessionScope.agentId,
          sessionScope.runId,
          limit,
          filters,
          true,
          threshold,
        ),
      );
    }

    return mergeSearchResults(results, limit);
  }

  const scopeIds = resolveToolScope(cfg, api, args, scope);
  if (scope === "session" && !scopeIds.runId) {
    return emptySearchResult();
  }

  return engine.search(
    args.query,
    scopeIds.userId,
    scopeIds.agentId,
    scopeIds.runId,
    limit,
    filters,
    true,
    threshold,
  );
}

async function listMemories(
  engine: Mem7Engine,
  cfg: PluginConfig,
  api: OpenClawPluginApi,
  args: ToolScopeArgs & { limit?: number },
  defaultScope: MemoryScope = "all",
): Promise<MemoryItem[]> {
  const scope = normalizeScope(args.scope, args.longTerm, defaultScope);
  const limit = args.limit ?? cfg.topK ?? 50;
  const filters = sourceFiltersJson();

  if (scope === "all") {
    const longTermScope = resolveToolScope(cfg, api, args, "long-term");
    const sessionScope = resolveToolScope(cfg, api, args, "session");

    const lists: MemoryItem[][] = [
      await engine.getAll(
        longTermScope.userId,
        longTermScope.agentId,
        longTermScope.runId,
        filters,
        limit,
      ),
    ];

    if (sessionScope.runId) {
      lists.push(
        await engine.getAll(
          sessionScope.userId,
          sessionScope.agentId,
          sessionScope.runId,
          filters,
          limit,
        ),
      );
    }

    return mergeMemoryLists(lists, limit);
  }

  const scopeIds = resolveToolScope(cfg, api, args, scope);
  if (scope === "session" && !scopeIds.runId) {
    return [];
  }

  return engine.getAll(scopeIds.userId, scopeIds.agentId, scopeIds.runId, filters, limit);
}

export function registerTools(
  api: OpenClawPluginApi,
  getEngine: EngineGetter,
  cfg: PluginConfig,
): void {
  api.registerTool({
    id: "memory_search",
    name: "memory_search",
    description:
      "Search long-term memory for facts, preferences, and relations relevant to a query. " +
      "Returns scored memories and graph relations.",
    parameters: Type.Object({
      query: Type.String({ description: "The search query" }),
      limit: Type.Optional(
        Type.Integer({
          description: "Max number of results",
          default: 5,
          minimum: 1,
          maximum: 50,
        }),
      ),
      userId: Type.Optional(Type.String({ description: "Override user ID" })),
      agentId: Type.Optional(Type.String({ description: "Optional agent scope" })),
      runId: Type.Optional(Type.String({ description: "Optional run/session scope" })),
      scope: ScopeSchema,
      longTerm: Type.Optional(
        Type.Boolean({ description: "Shortcut for scope=long-term when true" }),
      ),
    }),
    async execute(args: {
      query: string;
      limit?: number;
      userId?: string;
      agentId?: string;
      runId?: string;
      scope?: MemoryScope;
      longTerm?: boolean;
    }) {
      try {
        const engine = requireEngine(getEngine);
        const result = await searchMemories(engine, cfg, api, args, "all");
        return formatSearchResult(result);
      } catch (err) {
        return {
          content: [{ type: "text", text: `Memory search failed: ${String(err)}` }],
          details: { error: String(err) },
        };
      }
    },
  });

  api.registerTool({
    id: "memory_get",
    name: "memory_get",
    description:
      'Retrieve a specific memory by ID, or pass path="all" to list all stored memories.',
    parameters: Type.Object({
      path: Type.Optional(
        Type.String({
          description: 'Legacy memory path or "all" to list all memories',
        }),
      ),
      memoryId: Type.Optional(Type.String({ description: "Specific memory ID (preferred)" })),
      from: Type.Optional(Type.Integer({ description: "Pagination offset", minimum: 0 })),
      lines: Type.Optional(
        Type.Integer({
          description: "Number of results to return",
          minimum: 1,
          maximum: 100,
        }),
      ),
