    let history = engine.history(deleted_id).await.unwrap();
    assert_eq!(history.len(), 2);
    assert_eq!(history[0].action, MemoryAction::Add);
    assert_eq!(history[1].action, MemoryAction::Delete);
    assert!(history[1].is_deleted);
}

